#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-2.0-or-later
"""Regenerate the legacy COM tables after changing method mappings or d3d.itf."""
import re
from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]
interfaces={};name=None
for line in (ROOT / 'sdk/dx/d3d.itf').read_text().splitlines():
 if line.startswith('interface '):name=line.split()[1];interfaces[name]=[]
 elif line.startswith('HRESULT '):
  method,params=re.fullmatch(r'HRESULT (\w+)\((.*)\)',line).groups();interfaces[name].append((method,params))
common={'QueryInterface':'LQuery','AddRef':'LAdd','Release':'LRelease'}
root={'Initialize':'Initialized','CreateLight':'RootCreateLight','CreateMaterial':'RootCreateMaterial','CreateViewport':'RootCreateView','CreateDevice':'RootCreateDevice3'}
view={'Initialize':'Initialized','GetViewport':'ViewGet','SetViewport':'ViewSet','GetViewport2':'ViewGet2','SetViewport2':'ViewSet2','AddLight':'ViewAddLight','DeleteLight':'ViewDeleteLight','SetBackground':'ViewBackground','GetBackground':'ViewGetBackground','Clear':'ViewClear','Clear2':'ViewClear2'}
mat={'Initialize':'Initialized','SetMaterial':'MaterialSet','GetMaterial':'MaterialGet','GetHandle':'MaterialHandle','Reserve':'MaterialReserve','Unreserve':'MaterialReserve'}
light={'Initialize':'Initialized','SetLight':'LightSet','GetLight':'LightGet'}
exe={'Initialize':'ExecuteInitialize','Validate':'ExecuteValidate','Optimize':'ExecuteOptimize','Lock':'ExecuteLock','Unlock':'ExecuteUnlock','SetExecuteData':'ExecuteSet','GetExecuteData':'ExecuteGet'}
dev={'Initialize':'Initialized','AddViewport':'DeviceAddView','DeleteViewport':'DeviceDeleteView','SetCurrentViewport':'DeviceCurrent','GetCurrentViewport':'DeviceGetCurrent','BeginScene':'DeviceBeginScene','EndScene':'DeviceEndScene','DrawPrimitive':'DeviceDraw','DrawIndexedPrimitive':'DeviceDrawIndexed','SetLightState':'DeviceSetLightState','GetLightState':'DeviceGetLightState','CreateMatrix':'DeviceCreateMatrix','SetMatrix':'DeviceSetMatrix','GetMatrix':'DeviceGetMatrix','DeleteMatrix':'DeviceDeleteMatrix','CreateExecuteBuffer':'DeviceCreateExecute','Execute':'DeviceExecute','GetDirect3D':'DeviceGetRoot','SetRenderTarget':'DeviceSetTarget','GetRenderTarget':'DeviceGetTarget'}
dev.update({'SetRenderState':'DeviceSetRender','GetRenderState':'DeviceGetRender','NextViewport':'DeviceNextView','GetTexture':'DeviceGetTexture','SetTexture':'DeviceTexture','Begin':'DeviceBegin','BeginIndexed':'DeviceBeginIndexed','Vertex':'DeviceVertex','Index':'DeviceIndex','End':'DeviceEnd'})
view.update({'TransformVertices':'ViewTransform','LightElements':'ViewLightElements','NextLight':'ViewNextLight','SetBackgroundDepth':'ViewSetDepth','GetBackgroundDepth':'ViewGetDepth','SetBackgroundDepth2':'ViewSetDepth','GetBackgroundDepth2':'ViewGetDepth2'})
vb={'Lock':'LegacyVbLock','Unlock':'LegacyVbUnlock','GetVertexBufferDesc':'LegacyVbDesc','Optimize':'LegacyVbOptimize','ProcessVertices':'LegacyVbProcess'}
root.update({'FindDevice':'RootFind','CreateVertexBuffer':'RootVertexBuffer','EnumDevices':'RootEnum','EnumZBufferFormats':'RootZFormats','EvictManagedTextures':'RootEvict'})
dev.update({'SetTransform':'DeviceSetTransform','GetTransform':'DeviceGetTransform','MultiplyTransform':'DeviceMultiplyTransform','GetStats':'DeviceStats','DrawPrimitiveVB':'DeviceDrawVB','DrawIndexedPrimitiveVB':'DeviceDrawIndexedVB','GetCaps':'DeviceCaps','EnumTextureFormats':'DeviceFormats','SwapTextureHandles':'DeviceSwapTextures'})
forward={'GetRenderState','SetRenderState','SetTransform','GetTransform','MultiplyTransform','SetClipStatus','GetClipStatus','DrawPrimitiveStrided','DrawIndexedPrimitiveStrided','ComputeSphereVisibility','GetTextureStageState','SetTextureStageState','ValidateDevice'}
lines=['/* SPDX-License-Identifier: GPL-2.0-or-later */', '/* Generated by tools/generate_d3d_legacy_tables.py. Every slot has its public signature. */'];tables=[];families=[]
for prefix,names,mapping in [
 ('root',['IDirect3D','IDirect3D2','IDirect3D3'],root),('device',['IDirect3DDevice','IDirect3DDevice2','IDirect3DDevice3'],dev),('view',['IDirect3DViewport','IDirect3DViewport2','IDirect3DViewport3'],view),('material',['IDirect3DMaterial','IDirect3DMaterial2','IDirect3DMaterial3'],mat),('light',['IDirect3DLight'],light),('execute',['IDirect3DExecuteBuffer'],exe),('vertexbuffer',['IDirect3DVertexBuffer'],vb)]:
 pointers=[]
 for version,name in enumerate(names):
  entries=dict(common)
  for method,params in interfaces[name]:
   args=[re.search(r'(\w+)$',p).group(1) for p in params.split(',') if p]
   own=f'Legacy_{name}_{method}'
   if method in mapping:
    entries[method]= 'DeviceFormats3' if name=='IDirect3DDevice3' and method=='EnumTextureFormats' else 'RootCreateDevice2' if name=='IDirect3D2' and method=='CreateDevice' else mapping[method];continue
   lines.append(f'static HRESULT WINAPI {own}(void *face{", " if params else ""}{params})\n{{')
   if prefix=='device' and method in forward:
    lines.append('    DD_METHOD_LOCK();')
    lines.append('    LegacyDevice *d = (LegacyDevice*)Base(face);')
    lines.append(f'    return IDirect3DDevice7_{method}(d->core{", " if args else ""}{", ".join(args)});')
   else:
    lines += ['    (void)'+a+';' for a in ['face']+args]
    lines.append('    return DDERR_UNSUPPORTED;')
   lines.append('}')
   entries[method]=own
  table=f'{prefix}_table_{version}';pointers.append('&'+table)
  tables.append(f'static const struct {name}Vtbl {table} = {{\n'+',\n'.join('    .'+k+' = (void*)'+v for k,v in entries.items())+'\n};')
 if len(names)==3:families.append(f'static const void *{prefix}_tables[3] = {{'+', '.join(pointers)+'};')
 else:families.append(f'static const void *{prefix}_table = '+pointers[0]+';')
(ROOT / 'sdk/dx/ddraw/d3d_legacy_tables.inc').write_text('\n'.join(lines+tables+families)+'\n')
